using He_Thong_GYM.Models;using Microsoft.Data.SqlClient;using System.Data;
namespace He_Thong_GYM.DAL;
public sealed class LopTapDAL
{
 public async Task<List<LopTap>> LayDanhSachAsync(){const string q="SELECT l.MaLop,l.TenLop,l.MaLoaiLop,ll.TenLoaiLop,l.MaHLV,n.HoTen,l.SucChua,l.GioBatDau,l.GioKetThuc,l.TrangThai FROM dbo.LopTap l JOIN dbo.LoaiLopTap ll ON ll.MaLoaiLop=l.MaLoaiLop JOIN dbo.HuanLuyenVien h ON h.MaHLV=l.MaHLV JOIN dbo.NhanVien n ON n.MaNV=h.MaNV ORDER BY l.MaLop DESC;";var k=new List<LopTap>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new LopTap{MaLop=r.GetInt32(0),TenLop=r.GetString(1),MaLoaiLop=r.GetInt32(2),TenLoaiLop=r.GetString(3),MaHLV=r.GetInt32(4),TenHLV=r.GetString(5),SucChua=r.GetInt32(6),GioBatDau=r.GetTimeSpan(7),GioKetThuc=r.GetTimeSpan(8),TrangThai=r.GetString(9)});return k;}
 public async Task<List<(int MaLoai,string TenLoai)>> LayLoaiAsync(){var k=new List<(int,string)>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("SELECT MaLoaiLop,TenLoaiLop FROM dbo.LoaiLopTap ORDER BY TenLoaiLop",c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add((r.GetInt32(0),r.GetString(1)));return k;}
 public async Task ThemAsync(LopTap l){const string q="INSERT dbo.LopTap(TenLop,MaLoaiLop,MaHLV,SucChua,GioBatDau,GioKetThuc,TrangThai) VALUES(@Ten,@Loai,@HLV,@Suc,@BatDau,@KetThuc,@TrangThai);";await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.AddWithValue("@Ten",l.TenLop);m.Parameters.AddWithValue("@Loai",l.MaLoaiLop);m.Parameters.AddWithValue("@HLV",l.MaHLV);m.Parameters.AddWithValue("@Suc",l.SucChua);m.Parameters.AddWithValue("@BatDau",l.GioBatDau);m.Parameters.AddWithValue("@KetThuc",l.GioKetThuc);m.Parameters.AddWithValue("@TrangThai",l.TrangThai);await c.OpenAsync();await m.ExecuteNonQueryAsync();}
 public async Task<List<HocVienLop>> LayHocVienAsync(int maLop,DateTime ngay){const string q="SELECT d.MaDKL,t.MaTV,t.HoTen,t.SDT,dd.TrangThai FROM dbo.DangKyLop d JOIN dbo.ThanhVien t ON t.MaTV=d.MaTV LEFT JOIN dbo.DiemDanhLop dd ON dd.MaDKL=d.MaDKL AND dd.NgayDiemDanh=@Ngay WHERE d.MaLop=@MaLop AND d.TrangThai=N'Đang tham gia' ORDER BY t.HoTen;";var k=new List<HocVienLop>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.AddWithValue("@MaLop",maLop);m.Parameters.AddWithValue("@Ngay",ngay.Date);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new HocVienLop{MaDKL=r.GetInt32(0),MaTV=r.GetInt32(1),HoTen=r.GetString(2),SDT=r.GetString(3),TrangThaiDiemDanh=r.IsDBNull(4)?null:r.GetString(4)});return k;}
 public async Task DangKyLopAsync(int maTV,int maLop){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_DangKyLop",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaTV",maTV);m.Parameters.AddWithValue("@MaLop",maLop);m.Parameters.AddWithValue("@VaoDanhSachCho",true);var o=m.Parameters.Add("@MaDKL",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();}
 public async Task DiemDanhAsync(int maDKL,DateTime ngay,string tt){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_DiemDanhLop",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaDKL",maDKL);m.Parameters.AddWithValue("@NgayDiemDanh",ngay.Date);m.Parameters.AddWithValue("@TrangThai",tt);await c.OpenAsync();await m.ExecuteNonQueryAsync();}
}
